with gaps as (select *, case when lag(paid_at) over (partition by status order by paid_at, id) is null or paid_at > lag(paid_at) over (partition by status order by paid_at, id) + interval 14 days then 1 else 0 end as new_group_flag from payments) select id, method, paid_at, status, sum(new_group_flag) over (partition by status order by paid_at, id rows between unbounded preceding and current row) as burst_id from gaps;
